 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    nonbackground = Counter(v for row in grid for v in row if v != background)
    marker = nonbackground.most_common(1)[0][0]

    # The non-background, non-marker pixels define the motif. Its bounding-box
    # midpoint is the anchor aligned with each scattered marker.
    motif = [(r, c, grid[r][c])
             for r in range(h) for c in range(w)
             if grid[r][c] != background and grid[r][c] != marker]
    if not motif:
        return [row[:] for row in grid]
    r0 = min(r for r, c, v in motif)
    r1 = max(r for r, c, v in motif)
    c0 = min(c for r, c, v in motif)
    c1 = max(c for r, c, v in motif)
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2
    offsets = [(r - ar, c - ac, v) for r, c, v in motif]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for dr, dc, value in offsets:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out


